begin;
on conflict (term_id) do update set timezone=excluded.timezone;
on conflict (term_id,course_id) do update set title=excluded.title,credits_min=excluded.credits_min,credits_max=excluded.credits_max,prerequisites=excluded.prerequisites,corequisites=excluded.corequisites,pre_or_corequisites=excluded.pre_or_corequisites;
on conflict (section_id) do update set term_id=excluded.term_id,course_id=excluded.course_id,section_name=excluded.section_name,dependency_overrides=excluded.dependency_overrides;
on conflict (section_id,meeting_index) do update set days=excluded.days,start_time=excluded.start_time,end_time=excluded.end_time,schedule_type=excluded.schedule_type,start_date=excluded.start_date,end_date=excluded.end_date,end_day_offset=excluded.end_day_offset;
commit;
